#pragma once

// How a component looks, with CSS's names. Look only: geometry and layout are the component's own
// properties, so a theme changes how things look and never where they are (docs/ui-design.md,
// "Component API"). Every field is optional. A component takes a style value, a theme's or one
// extended from it:
//
//   .style = ui::styles::pane.extend({.backgroundColor = player.color})
//
// A theme style (ui::styles::*, generated by salal_tokens()) sets `theme` and nothing else. Mounted, a
// component resolves its style against its scene's theme: its type's theme style, then the one
// `theme` names, then its own set fields; what's still unset is the type's hard-coded default.

#include "ui/theme/TokenTable.h"

#include <graphics/Color.h>
#include <graphics/PrimitiveStyles.h>
#include <primitives/FontFamily.h>

#include <cstdint>
#include <optional>

namespace ui {

	// How a border or a line is stroked: solid, CSS's dashed and dotted, sized by the stroke's width,
	// or a dash pattern in px (a strokeStyle token's dashArray and lineCap).
	struct StrokeStyle {
		enum class Kind : std::uint8_t { Solid, Dashed, Dotted, Pattern };

		Kind					kind = Kind::Solid;
		Foundation::DashPattern pattern{}; // Pattern's

		// The renderer's dash for a stroke `width` wide: none when solid; dashed, 3 widths on and 3
		// off; dotted, round dots a width across with a width between them.
		[[nodiscard]] std::optional<Foundation::DashPattern> dash(float width) const;
	};

	struct Style {
		std::optional<Foundation::Color>		   backgroundColor;
		std::optional<Foundation::Color>		   borderColor;
		std::optional<float>					   borderWidth; // px, inside the box
		std::optional<StrokeStyle>				   borderStyle; // a border's, and a Line's stroke
		std::optional<Foundation::BorderSides>	   borderSides; // unset, all four; from salal's extension in a theme
		std::optional<float>					   borderRadius;
		std::optional<Foundation::BoxShadow>	   boxShadow;
		std::optional<float>					   opacity;	   // 0 to 1, multiplied down the tree
		std::optional<Foundation::Color>		   color;	   // text, and a line's stroke
		std::optional<Foundation::BoxShadow>	   textShadow; // with a spread, a halo's width (Primitives::drawGlyphShadow)
		std::optional<Renderer::FontFamily>		   fontFamily;
		std::optional<float>					   fontSize; // px
		std::optional<Foundation::HorizontalAlign> textAlign;
		std::optional<Foundation::VerticalAlign>   verticalAlign;
		std::optional<float>					   letterSpacing; // px between glyphs
		std::optional<Foundation::TextTransform>   textTransform;
		// Picks the face: resolved against the theme, fontFamily becomes the family registered under
		// its name nearest this weight (ThemeArgs::fontFamilies), so a role's bold is a weight, not a
		// family of its own. Unset, the family is as given.
		std::optional<float> fontWeight;
		// Carried from the tokens; nothing reads it yet (wrapped text takes its line height from the
		// atlas).
		std::optional<float> lineHeight; // a multiple of fontSize
		StyleId				 theme;		 // the theme style this one extends, if any

		// A copy with the overrides' set fields on top, as JS spreads {...pane, backgroundColor}; the
		// overrides' theme replaces this one's only if they name one.
		[[nodiscard]] Style extend(const Style& overrides) const;
	};

} // namespace ui
